int pidfd;           // File descriptor referring to the target process
int targetfd = 1;    // The remote FD number (e.g., STDOUT_FILENO)
unsigned int flags = 0; // Must be 0 for now
int new_local_fd;

// Duplicate targetfd from the process referenced by pidfd
new_local_fd = pidfd_getfd(
    pidfd,
    targetfd,
    flags
);

// New FD shares the same open file description (offset, flags)
// as the original file descriptor in the target process.
